/**
 * Reads the cached project graph, returning `null` when it is unavailable
 * (e.g. it has not been computed yet). Completion runs on a fast path and must
 * never build the graph itself, so a missing cache simply yields no
 * suggestions.
 */
function tryReadProjectGraph(): ProjectGraph | null {
  try {
    return readCachedProjectGraph();
  } catch {
    return null;
  }
}

/**
 * Returns all project names from the cached project graph that start with the
 * given prefix. Returns `[]` when the project graph is unavailable.
 */
export function getProjectNameCompletions(prefix: string): string[] {
  const graph = tryReadProjectGraph();
  if (!graph) {
    return [];
  }
  return Object.keys(graph.nodes).filter((name) => name.startsWith(prefix));
}

/**
 * Returns project names that start with the given prefix AND declare a target
 * matching the given target name. Returns `[]` when nothing matches or the
 * graph is unavailable.
 */
export function getProjectNamesWithTarget(
  prefix: string,
  target: string
): string[] {
  const graph = tryReadProjectGraph();
  if (!graph) {
    return [];
  }
  return Object.keys(graph.nodes).filter((name) => {
    if (!name.startsWith(prefix)) {
      return false;
    }
    const targets = graph.nodes[name]?.data?.targets;
    return !!targets && !!targets[target];
  });
}

/**
 * Returns the unique set of target names across all workspace projects that
 * start with the given prefix. Returns `[]` when the graph is unavailable.
 */
export function getTargetNameCompletions(prefix: string): string[] {
  const graph = tryReadProjectGraph();
  if (!graph) {
    return [];
  }
  const targets = new Set<string>();
  for (const node of Object.values(graph.nodes)) {
    for (const target of Object.keys(node.data?.targets ?? {})) {
      if (target.startsWith(prefix)) {
        targets.add(target);
      }
    }
  }
  return [...targets];
}

/**
 * Returns target names for a specific project that start with the given prefix.
 * When the project name does not exist in the graph, falls back to all
 * workspace target names — this supports partial project-name typing scenarios
 * like `project:t<TAB>` where `project` has not been fully typed yet.
 */
export function getTargetNamesForProject(
  prefix: string,
  projectName: string
): string[] {
  const graph = tryReadProjectGraph();
  if (!graph) {
    return [];
  }
  const node = graph.nodes[projectName];
  if (!node) {
    return getTargetNameCompletions(prefix);
  }
  return Object.keys(node.data?.targets ?? {}).filter((target) =>
    target.startsWith(prefix)
  );
}

/**
 * Two-stage completion for `project:target` tokens.
 *
 * - Stage 1 (no colon in `current`): returns matching project names, each
 *   suffixed with `:` so the user can continue typing the target.
 * - Stage 2 (colon present): returns `projectName:targetName` candidates
 *   matching the portion typed after the colon. If the project name is unknown,
 *   all workspace targets are offered.
 */
export function completeProjectTarget(current: string): string[] {
  const colonIndex = current.indexOf(':');
  if (colonIndex === -1) {
    return getProjectNameCompletions(current).map((name) => `${name}:`);
  }

  const projectName = current.slice(0, colonIndex);
  const targetPrefix = current.slice(colonIndex + 1);
  return getTargetNamesForProject(targetPrefix, projectName).map(
    (target) => `${projectName}:${target}`
  );
}

