export type CompletionFn = (current: string, args: string[]) => string[];

/**
 * Describes how to complete a single positional argument — either via a fixed
 * set of `choices` (filtered by prefix) or a dynamic `complete` function.
 */
export interface PositionalCompletion {
  choices?: string[];
  complete?: CompletionFn;
}

/**
 * Completion metadata for a single command path.
