export interface CompletionMetadata {
  positionals?: PositionalCompletion[];
  flags?: Record<string, CompletionFn>;
}

// Command path (space-separated tokens, e.g. `show target`) -> metadata.
const registry = new Map<string, CompletionMetadata>();

/**
 * Registers completion metadata for a command path. The path is a
 * space-separated string of command tokens (e.g. `'show target'`).
 */
export function registerCompletion(
  path: string,
  metadata: CompletionMetadata
): void {
  registry.set(path, metadata);
}

/**
 * Test/internal helper: removes all registered completion metadata.
 */
export function clearCompletionRegistry(): void {
  registry.clear();
}

function isFlagToken(token: string): boolean {
  return token.startsWith('--');
}

/**
 * Searches the registry for the longest registered path that is a prefix of the
 * given tokens array. Flag tokens (starting with `--`) halt the prefix walk.
 *
 * The final token is treated as the partial value being completed and is never
 * consumed as part of the matched path or counted as a completed positional.
 *
 * @returns The matching metadata plus the `positionalIndex` — the count of
 * non-flag tokens typed beyond the matched path (excluding the token currently
 * being completed) — or `null` when no path matches.
 */
export function findCompletionMetadata(
  tokens: string[]
): { metadata: CompletionMetadata; positionalIndex: number } | null {
  if (!tokens || tokens.length === 0) {
    return null;
  }

  // The last token is the partial being completed; the path is built from the
  // tokens that precede it.
  const completed = tokens.slice(0, tokens.length - 1);

  // Build the candidate path prefix, halting at the first flag token.
  const walk: string[] = [];
  for (const token of completed) {
    if (isFlagToken(token)) {
      break;
    }
    walk.push(token);
  }

  // Find the longest registered path that matches a prefix of the walk.
  let matchedLength = -1;
  let metadata: CompletionMetadata | undefined;
  for (let len = walk.length; len >= 1; len--) {
    const candidate = walk.slice(0, len).join(' ');
    if (registry.has(candidate)) {
      matchedLength = len;
      metadata = registry.get(candidate);
      break;
    }
  }

  if (!metadata) {
    return null;
  }

  // Count non-flag tokens typed beyond the matched path (the current partial is
  // already excluded since it is not part of `completed`).
  const positionalIndex = completed
    .slice(matchedLength)
    .filter((token) => !isFlagToken(token)).length;

  return { metadata, positionalIndex };
}

/**
 * Looks up the flag completion handler for a given flag name. Leading dashes
 * are stripped before lookup, so `--projects` and `projects` resolve to the
 * same handler. Returns `null` when metadata is `null` or no handler exists.
 */
export function findFlagCompletion(
  metadata: CompletionMetadata | null,
  flag: string
): CompletionFn | null {
  if (!metadata || !metadata.flags) {
    return null;
  }
  const normalized = flag.replace(/^-+/, '');
  return metadata.flags[normalized] ?? metadata.flags[flag] ?? null;
