 * Resolves completion candidates for the given tokens.
 *
 * Flag dispatch takes precedence over positional dispatch: if `previousToken`
 * starts with `--`, a registered flag handler is invoked (returning `[]` when
 * no handler is registered — there is no fallthrough to positionals).
 * Otherwise the positional completer at the computed `positionalIndex` is
 * dispatched (via `complete(current, tokens)` or by filtering `choices`).
 *
 * @returns The candidate list, or `null` for empty tokens, no metadata match,
 * or a positional index beyond the declared positionals.
 */
export function resolveCompletion(
  tokens: string[],
  current: string,
  previousToken: string
): string[] | null {
  if (!tokens || tokens.length === 0) {
    return null;
  }

  const found = findCompletionMetadata(tokens);
  if (!found) {
    return null;
  }

  const { metadata, positionalIndex } = found;

  // Flag dispatch takes precedence. Once we know the previous token is a flag,
  // we never fall through to positional completion.
  if (isFlagToken(previousToken)) {
    const handler = findFlagCompletion(metadata, previousToken);
    if (handler) {
      return handler(current, tokens);
