const BEGIN = '###-begin-nx-completions-###';
const END = '###-end-nx-completions-###';

/**
 * bash completion script.
 *
 * Walks up from the current directory to locate the workspace-local nx binary,
 * then invokes it with `NX_COMPLETE=bash` so nx emits completion candidates on
 * stdout (one per line). `env` is used to set the variables inline so the exact
 * `NX_COMPLETE=bash` token is present.
 */
function bashScript(): string {
  return `${BEGIN}
_nx_completions() {
  local nx_bin dir
  dir="$PWD"
  nx_bin=""
  while [ "$dir" != "/" ] && [ -n "$dir" ]; do
    if [ -x "$dir/node_modules/.bin/nx" ]; then
      nx_bin="$dir/node_modules/.bin/nx"
      break
    fi
    if [ -x "$dir/.nx/installation/node_modules/.bin/nx" ]; then
      nx_bin="$dir/.nx/installation/node_modules/.bin/nx"
      break
    fi
    dir="$(dirname "$dir")"
  done
  if [ -z "$nx_bin" ]; then
    nx_bin="nx"
  fi

  local IFS=$'\\n'
  local completions
  completions="$(env NX_COMPLETE=bash NX_VERBOSE_LOGGING=false "$nx_bin" "\${COMP_WORDS[@]:1}" 2>/dev/null)"
  COMPREPLY=( $(compgen -W "$completions" -- "\${COMP_WORDS[COMP_CWORD]}") )
  return 0
}
complete -o default -o bashdefault -F _nx_completions nx
${END}
`;
}

/**
 * zsh completion script.
 *
 * zsh renders descriptions, so completions are split on TAB into a value and a
 * description and passed to \`compadd -d\`. \`_describe\` is intentionally NOT used.
 */
function zshScript(): string {
  return `${BEGIN}
_nx_completions() {
  local nx_bin dir
  dir="$PWD"
  nx_bin=""
  while [ "$dir" != "/" ] && [ -n "$dir" ]; do
    if [ -x "$dir/node_modules/.bin/nx" ]; then
      nx_bin="$dir/node_modules/.bin/nx"
      break
    fi
    if [ -x "$dir/.nx/installation/node_modules/.bin/nx" ]; then
      nx_bin="$dir/.nx/installation/node_modules/.bin/nx"
      break
    fi
    dir="$(dirname "$dir")"
  done
  if [ -z "$nx_bin" ]; then
    nx_bin="nx"
  fi

  local -a values displays
  local line value desc
  local completions
  completions="$(env NX_COMPLETE=zsh NX_VERBOSE_LOGGING=false "$nx_bin" "\${words[@]:1}" 2>/dev/null)"
  while IFS=$'\\t' read -r value desc; do
    [ -z "$value" ] && continue
    values+=("$value")
    if [ -n "$desc" ]; then
      displays+=("$value -- $desc")
    else
      displays+=("$value")
    fi
  done <<< "$completions"

  compadd -d displays -a values
}
compdef _nx_completions nx
${END}
`;
}

/**
 * fish completion script.
 */
function fishScript(): string {
  return `${BEGIN}
function __nx_complete
  set -l dir $PWD
  set -l nx_bin ""
  while test "$dir" != "/"; and test -n "$dir"
    if test -x "$dir/node_modules/.bin/nx"
      set nx_bin "$dir/node_modules/.bin/nx"
      break
    end
    if test -x "$dir/.nx/installation/node_modules/.bin/nx"
      set nx_bin "$dir/.nx/installation/node_modules/.bin/nx"
      break
    end
    set dir (dirname "$dir")
  end
  test -z "$nx_bin"; and set nx_bin nx

  set -l tokens (commandline -opc)
  env NX_COMPLETE=fish NX_VERBOSE_LOGGING=false $nx_bin $tokens[2..-1] 2>/dev/null
end
complete -c nx -f -a '(__nx_complete)'
${END}
`;
}

/**
 * PowerShell completion script.
 */
function powershellScript(): string {
  return `${BEGIN}
$scriptblock = {
  param($wordToComplete, $commandAst, $cursorPosition)

  $dir = $PWD.Path
  $nx_bin = $null
  while ($dir -and ($dir -ne [System.IO.Path]::GetPathRoot($dir))) {
    if (Test-Path "$dir\\node_modules\\.bin\\nx.cmd") {
      $nx_bin = "$dir\\node_modules\\.bin\\nx.cmd"
      break
    }
    if (Test-Path "$dir\\.nx\\installation\\node_modules\\.bin\\nx.cmd") {
      $nx_bin = "$dir\\.nx\\installation\\node_modules\\.bin\\nx.cmd"
      break
    }
    $dir = Split-Path $dir -Parent
  }
  if (-not $nx_bin) { $nx_bin = "nx" }

  $env:NX_COMPLETE = 'powershell'
  $env:NX_VERBOSE_LOGGING = 'false'

  $words = $commandAst.CommandElements | Select-Object -Skip 1 | ForEach-Object { $_.ToString() }
  & $nx_bin $words 2>$null | ForEach-Object {
    $parts = $_ -split "\`t", 2
    $value = $parts[0]
    $desc = if ($parts.Length -gt 1 -and $parts[1]) { $parts[1] } else { $value }
    [System.Management.Automation.CompletionResult]::new($value, $value, 'ParameterValue', $desc)
  }
}
Register-ArgumentCompleter -Native -CommandName nx -ScriptBlock $scriptblock
${END}
`;
}

/**
 * Generates a shell completion installation script for the given shell.
 *
 * The returned script sets `NX_COMPLETE` to the target shell name, discards
 * stderr, disables verbose logging, and walks up the directory tree to find the
 * workspace-local nx binary before invoking it to produce completion
 * candidates.
 */
export async function generateScript(shell: CompletionShell): Promise<string> {
  switch (shell) {
    case 'bash':
      return bashScript();
    case 'zsh':
      return zshScript();
    case 'fish':
      return fishScript();
    case 'powershell':
      return powershellScript();
    default:
      throw new Error(`Unsupported shell for nx completions: ${shell}`);
  }
}
